import { RouteObject } from 'react-router-dom';
import { lazy } from 'react';
import HomePage from './pages/index';
import ProdNotFoundPage from './pages/_404';

const NotFoundPage = import.meta.env.DEV
  ? lazy(() => import('../dev-tools/src/PageNotFound'))
  : ProdNotFoundPage;

const ProductsPage = lazy(() => import('./pages/products'));
const AboutPage = lazy(() => import('./pages/about'));

export const routes: RouteObject[] = [
  {
    path: '/',
    element: <HomePage />,
  },
  {
    path: '/products',
    element: <ProductsPage />,
  },
  {
    path: '/about',
    element: <AboutPage />,
  },
  {
    path: '*',
    element: <NotFoundPage />,
  },
];

export type Path = '/' | '/products' | '/about';
export type Params = Record<string, string | undefined>;

import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';

const navItems = [
  { href: '/', label: 'Home' },
  { href: '/products', label: 'Shop' },
  { href: '/about', label: 'About' },
];

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <header className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b border-border">
      <div className="container mx-auto px-6">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Artisan Goods Co. home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Artisan Goods Co."
              className="h-10 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8" aria-label="Main navigation">
            {navItems.map((item) => {
              const isActive =
                item.href === '/'
                  ? location.pathname === '/'
                  : location.pathname.startsWith(item.href);
              return (
                <Link
                  key={item.href}
                  to={item.href}
                  className={`relative text-sm font-medium tracking-wide transition-colors group ${
                    isActive ? 'text-primary' : 'text-foreground hover:text-primary'
                  }`}
                >
                  {item.label}
                  {/* Animated underline */}
                  <span
                    className={`absolute -bottom-1 left-0 h-0.5 bg-primary transition-all duration-300 ${
                      isActive ? 'w-full' : 'w-0 group-hover:w-full'
                    }`}
                  />
                </Link>
              );
            })}
            <Link
              to="/products"
              className="ml-2 px-5 py-2 bg-primary text-primary-foreground text-sm font-medium rounded-full hover:bg-primary/90 transition-colors"
            >
              Shop Now
            </Link>
          </nav>

          {/* Mobile hamburger */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 rounded-md text-foreground hover:bg-muted transition-colors"
            aria-label="Toggle menu"
            aria-expanded={isMobileMenuOpen}
          >
            {isMobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      {/* Mobile drawer */}
      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.25, ease: 'easeOut' }}
            className="md:hidden overflow-hidden border-t border-border bg-background"
          >
            <nav className="flex flex-col px-6 py-4 gap-1" aria-label="Mobile navigation">
              {navItems.map((item) => {
                const isActive =
                  item.href === '/'
                    ? location.pathname === '/'
                    : location.pathname.startsWith(item.href);
                return (
                  <Link
                    key={item.href}
                    to={item.href}
                    className={`py-3 text-base font-medium border-b border-border last:border-0 transition-colors ${
                      isActive ? 'text-primary' : 'text-foreground hover:text-primary'
                    }`}
                    onClick={() => setIsMobileMenuOpen(false)}
                  >
                    {item.label}
                  </Link>
                );
              })}
              <Link
                to="/products"
                className="mt-3 px-5 py-2.5 bg-primary text-primary-foreground text-sm font-medium rounded-full text-center hover:bg-primary/90 transition-colors"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Shop Now
              </Link>
            </nav>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'motion/react';
import { ArrowRight, Leaf } from 'lucide-react';
import { Helmet } from '@dr.pogodin/react-helmet';

interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  image: string;
}

const categoryColors: Record<string, string> = {
  pottery: 'bg-primary/10 text-primary',
  textiles: 'bg-accent/10 text-accent',
  woodwork: 'bg-secondary/10 text-secondary-foreground',
  jewelry: 'bg-muted text-muted-foreground',
};

function ProductCard({ product, index }: { product: Product; index: number }) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.08, ease: 'easeOut' }}
      whileHover={{ y: -4 }}
      className="group bg-card rounded-2xl overflow-hidden shadow-sm hover:shadow-lg transition-shadow duration-300 cursor-pointer"
    >
      <div className="aspect-square overflow-hidden bg-muted">
        <img
          src={product.image}
          alt={product.name}
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
          loading="lazy"
        />
      </div>
      <div className="p-4">
        <span
          className={`inline-block text-xs font-medium px-2.5 py-1 rounded-full capitalize mb-2 ${
            categoryColors[product.category] ?? 'bg-muted text-muted-foreground'
          }`}
        >
          {product.category}
        </span>
        <h3 className="font-semibold text-card-foreground text-base leading-snug mb-1">
          {product.name}
        </h3>
        <p className="text-primary font-semibold">${product.price}</p>
      </div>
    </motion.div>
  );
}

export default function HomePage() {
  const [featured, setFeatured] = useState<Product[]>([]);
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  useEffect(() => {
    fetch('/api/products?featured=true')
      .then((r) => r.json())
      .then((data: Product[]) => setFeatured(data.slice(0, 4)))
      .catch(() => {});
  }, []);

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) {
      setSubscribed(true);
      setEmail('');
    }
  };

  return (
    <>
      <Helmet>
        <title>Artisan Goods Co. — Handcrafted with Heart</title>
        <meta
          name="description"
          content="Discover handmade pottery, textiles, woodwork, and jewelry from independent artisans. Every piece tells a story."
        />
      </Helmet>

      {/* ── Hero ── */}
      <section className="relative min-h-[90vh] flex items-center overflow-hidden">
        {/* Background image */}
        <div className="absolute inset-0">
          <img
            src="/airo-assets/images/pages/home/hero"
            alt="Artisan at work"
            className="w-full h-full object-cover"
            fetchPriority="high"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-gray-900/75 via-gray-900/50 to-transparent" />
        </div>

        {/* Hero content */}
        <div className="relative container mx-auto px-6 py-24">
          <div className="max-w-xl">
            <motion.p
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, ease: 'easeOut' }}
              className="text-primary text-sm font-medium uppercase tracking-widest mb-4 flex items-center gap-2"
            >
              <Leaf size={14} />
              Handmade with intention
            </motion.p>
            <motion.h1
              initial={{ opacity: 0, y: 24 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.55, delay: 0.1, ease: 'easeOut' }}
              className="font-heading text-5xl md:text-7xl font-bold text-white leading-tight mb-6"
            >
              Handcrafted
              <br />
              <span className="text-primary">with Heart</span>
            </motion.h1>
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.2, ease: 'easeOut' }}
              className="text-white/80 text-lg leading-relaxed mb-8 max-w-md"
            >
              Every piece in our collection is made by hand, by people who love what they do.
              Discover pottery, textiles, woodwork, and jewelry that carry the warmth of their maker.
            </motion.p>
            <motion.div
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.3, ease: 'easeOut' }}
              className="flex flex-wrap gap-4"
            >
              <Link
                to="/products"
                className="inline-flex items-center gap-2 px-7 py-3.5 bg-primary text-primary-foreground font-medium rounded-full hover:bg-primary/90 transition-colors text-sm"
              >
                Shop the Collection
                <ArrowRight size={16} />
              </Link>
              <Link
                to="/about"
                className="inline-flex items-center gap-2 px-7 py-3.5 bg-white/10 text-white border border-white/30 font-medium rounded-full hover:bg-white/20 transition-colors text-sm backdrop-blur-sm"
              >
                Our Story
              </Link>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ── Category strip ── */}
      <section className="bg-muted py-6 border-y border-border">
        <div className="container mx-auto px-6">
          <div className="flex flex-wrap justify-center gap-3 md:gap-8">
            {['Pottery', 'Textiles', 'Woodwork', 'Jewelry'].map((cat) => (
              <Link
                key={cat}
                to={`/products?category=${cat.toLowerCase()}`}
                className="text-sm font-medium text-muted-foreground hover:text-primary transition-colors uppercase tracking-widest"
              >
                {cat}
              </Link>
            ))}
          </div>
        </div>
      </section>

      {/* ── Featured Products ── */}
      <section className="py-20 container mx-auto px-6">
        <div className="flex items-end justify-between mb-12">
          <div>
            <p className="text-primary text-sm font-medium uppercase tracking-widest mb-2">
              Handpicked
            </p>
            <h2 className="font-heading text-4xl md:text-5xl font-bold text-foreground">
              Our Favorites
            </h2>
          </div>
          <Link
            to="/products"
            className="hidden md:inline-flex items-center gap-2 text-sm font-medium text-primary hover:gap-3 transition-all"
          >
            View all <ArrowRight size={16} />
          </Link>
        </div>

        {featured.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {featured.map((product, i) => (
              <ProductCard key={product.id} product={product} index={i} />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="bg-muted rounded-2xl overflow-hidden animate-pulse">
                <div className="aspect-square bg-border" />
                <div className="p-4 flex flex-col gap-2">
                  <div className="h-4 bg-border rounded w-1/3" />
                  <div className="h-5 bg-border rounded w-3/4" />
                  <div className="h-4 bg-border rounded w-1/4" />
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="mt-10 text-center md:hidden">
