import { useEffect, useState, useCallback } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { motion } from 'motion/react';
import { ChevronRight } from 'lucide-react';
import { Helmet } from '@dr.pogodin/react-helmet';

interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  image: string;
  description: string;
}

type Category = 'all' | 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

const CATEGORIES: { value: Category; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'pottery', label: 'Pottery' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

const categoryColors: Record<string, string> = {
  pottery: 'bg-primary/10 text-primary',
  textiles: 'bg-accent/10 text-accent',
  woodwork: 'bg-secondary/10 text-secondary-foreground',
  jewelry: 'bg-muted text-muted-foreground',
};

function ProductSkeleton() {
  return (
    <div className="bg-card rounded-2xl overflow-hidden animate-pulse">
      <div className="aspect-square bg-muted" />
      <div className="p-4 flex flex-col gap-2">
        <div className="h-4 bg-muted rounded w-1/3" />
        <div className="h-5 bg-muted rounded w-3/4" />
        <div className="h-4 bg-muted rounded w-1/4" />
      </div>
    </div>
  );
}

function ProductCard({ product, index }: { product: Product; index: number }) {
  return (
    <motion.article
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35, delay: Math.min(index * 0.05, 0.4), ease: 'easeOut' }}
      whileHover={{ y: -4 }}
      className="group bg-card rounded-2xl overflow-hidden shadow-sm hover:shadow-lg transition-shadow duration-300"
    >
      <div className="aspect-square overflow-hidden bg-muted">
        <img
          src={product.image}
          alt={product.name}
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
          loading="lazy"
        />
      </div>
      <div className="p-4">
        <span
          className={`inline-block text-xs font-medium px-2.5 py-1 rounded-full capitalize mb-2 ${
            categoryColors[product.category] ?? 'bg-muted text-muted-foreground'
          }`}
        >
          {product.category}
        </span>
        <h3 className="font-semibold text-card-foreground text-base leading-snug mb-1">
          {product.name}
        </h3>
        <p className="text-muted-foreground text-xs leading-relaxed mb-3 line-clamp-2">
          {product.description}
        </p>
        <div className="flex items-center justify-between">
          <span className="text-primary font-semibold">${product.price}</span>
          <button className="text-xs font-medium text-muted-foreground hover:text-primary transition-colors">
            Add to cart
          </button>
        </div>
      </div>
    </motion.article>
  );
}

export default function ProductsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const initialCategory = (searchParams.get('category') as Category) ?? 'all';

  const [activeCategory, setActiveCategory] = useState<Category>(initialCategory);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchProducts = useCallback(async (category: Category) => {
    setLoading(true);
    try {
      const url =
        category === 'all' ? '/api/products' : `/api/products?category=${category}`;
      const res = await fetch(url);
      const data: Product[] = await res.json();
      setProducts(data);
    } catch {
      setProducts([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchProducts(activeCategory);
  }, [activeCategory, fetchProducts]);

  // Sync URL param → state on mount
  useEffect(() => {
    const cat = (searchParams.get('category') as Category) ?? 'all';
    setActiveCategory(cat);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    if (cat === 'all') {
      setSearchParams({});
    } else {
      setSearchParams({ category: cat });
    }
  };

  const categoryLabel =
    CATEGORIES.find((c) => c.value === activeCategory)?.label ?? 'All';

  return (
    <>
      <Helmet>
        <title>Shop — Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse our full collection of handmade pottery, textiles, woodwork, and jewelry from independent artisans."
        />
      </Helmet>

      {/* Page header */}
      <div className="bg-muted border-b border-border">
        <div className="container mx-auto px-6 py-10">
          {/* Breadcrumb */}
          <nav className="flex items-center gap-1.5 text-xs text-muted-foreground mb-4" aria-label="Breadcrumb">
            <Link to="/" className="hover:text-foreground transition-colors">
              Home
            </Link>
            <ChevronRight size={12} />
            <span className="text-foreground font-medium">Shop</span>
            {activeCategory !== 'all' && (
              <>
                <ChevronRight size={12} />
                <span className="text-foreground font-medium capitalize">{categoryLabel}</span>
              </>
            )}
          </nav>
          <h1 className="font-heading text-4xl md:text-5xl font-bold text-foreground">
            {activeCategory === 'all' ? 'All Products' : categoryLabel}
          </h1>
          <p className="text-muted-foreground mt-2 text-sm">
            {loading ? '…' : `${products.length} piece${products.length !== 1 ? 's' : ''}`}
          </p>
        </div>
      </div>

      <div className="container mx-auto px-6 py-10">
        {/* Category filter tabs */}
        <div
          className="flex flex-wrap gap-2 mb-10"
          role="tablist"
          aria-label="Filter by category"
        >
          {CATEGORIES.map((cat) => (
            <button
              key={cat.value}
              role="tab"
              aria-selected={activeCategory === cat.value}
              onClick={() => handleCategoryChange(cat.value)}
              className={`px-5 py-2 rounded-full text-sm font-medium transition-colors ${
                activeCategory === cat.value
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground hover:bg-border hover:text-foreground'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>

        {/* Product grid */}
        {loading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {[...Array(6)].map((_, i) => (
              <ProductSkeleton key={i} />
            ))}
          </div>
        ) : products.length === 0 ? (
          <div className="text-center py-24">
            <p className="font-heading text-2xl text-muted-foreground mb-4">No products found</p>
            <button
              onClick={() => handleCategoryChange('all')}
              className="text-primary text-sm font-medium hover:underline"
            >
              View all products
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {products.map((product, i) => (
              <ProductCard key={product.id} product={product} index={i} />
            ))}
          </div>
        )}
      </div>
    </>
  );
}

