/**
 * Products Service
 *
 * All product data fetching goes through this module.
 * Components import these functions rather than calling fetch() directly.
 */

export interface Product {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  image: string;
  description: string;
  featured?: boolean;
}

export type Category = 'all' | 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

export const CATEGORIES: { value: Category; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'pottery', label: 'Pottery' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

export const CATEGORY_COLORS: Record<string, string> = {
  pottery: 'bg-primary/10 text-primary',
  textiles: 'bg-accent/10 text-accent',
  woodwork: 'bg-secondary/10 text-secondary-foreground',
  jewelry: 'bg-muted text-muted-foreground',
};

/**
 * Fetch all products, optionally filtered by category.
 */
export async function fetchProducts(category: Category = 'all'): Promise<Product[]> {
  const url =
    category === 'all' ? '/api/products' : `/api/products?category=${category}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Failed to fetch products: ${res.status}`);
  return res.json() as Promise<Product[]>;
}

/**
 * Fetch only featured products.
 */
export async function fetchFeaturedProducts(): Promise<Product[]> {
  const res = await fetch('/api/products?featured=true');
  if (!res.ok) throw new Error(`Failed to fetch featured products: ${res.status}`);
  return res.json() as Promise<Product[]>;
}

